Autoloader::register();Autoloader::addNamespace('Berserk\\',__DIR__.'/../src/');
set_error_handler(static function($n,$m,$f,$l){if(error_reporting()&$n)throw new ErrorException($m,0,$n,$f,$l);return false;});
$defs=[];foreach(json_decode(file_get_contents(__DIR__.'/movement-s1-fixture.json'),true,512,JSON_THROW_ON_ERROR)as$d)$defs[$d['ukid']]=$d;
function check(bool $v,string $why):void{if(!$v)throw new RuntimeException($why);}
function sc(int $id,string $ukid,string $owner,int $row,int $col):CardInstance{global $defs;$d=$defs[$ukid];return new CardInstance(instanceId:$id,ukid:$ukid,owner:$owner,zone:'field',row:$row,col:$col,hp:(int)$d['health'],hpMax:(int)$d['health'],move:(int)$d['move'],moveMax:(int)$d['move'],strikeWeak:(int)$d['strike_weak'],strikeMedium:(int)$d['strike_medium'],strikeStrong:(int)$d['strike_strong'],prop:json_decode($d['prop']??'{}',true)?:[]);}
function seed(string $ukid='s1_17',int $distance=2):GameState{$s=new GameState(91,101,202);$s->status='battle';$s->battle=['active'=>'host','turn'=>1,'strike'=>null];$s->addCard(sc(1,$ukid,'host',3,3));$s->addCard(sc(2,'s1_128','player',3+$distance,3));$s->addCard(sc(3,'s1_1','host',1,1));$s->addCard(sc(4,'s1_1','player',6,5));return$s;}
function cmd(GameState $s,string $actor,string $type,array $p=[]):mixed{$r=(new Engine(clock:fn()=>1800000000))->apply($s,$actor,new Command($type,$p));check($r->success,$type.': '.($r->error??''));return$r;}
function es(array $events,string $type):array{return array_values(array_filter($events,fn($e)=>$e['type']===$type));}
$results=[];$examples=[];
function pair(string $name,GameState $seed,Closure $run,Closure $verify,string $queue='4,6,2,5,3,1'):void{
 global $defs,$results,$examples;$out=[];
 foreach([false,true]as$observed){$_SESSION=['debug_roll'=>$queue];Dice::init();$s=GameState::fromArray($seed->toArray());$rec=$observed?new Recorder(91,1,[],[],true,fn($c)=>$defs[$c->ukid]['name']??null):null;$s->historyRecorder=$rec;$r=$run($s);$out[]=[$s->toArray(),serialize($r),Dice::remaining()];if($rec){$events=$rec->batch($s)->data()['events'];$verify($events,$s);if(true)$examples[$name]['structured']=array_map(fn($e)=>array_intersect_key($e,array_flip(['type','host','player'])),array_values(array_filter($events,fn($e)=>in_array($e['type'],['movement.completed','zone.changed','card.transformed'],true))));foreach(['host','player']as$view){$lines=[];foreach($events as$e)if($e[$view]!==null&&($t=JournalText::format($e['type'],$e[$view],$view))!==null)$lines[]=$t;$examples[$name][$view]=$lines;}}}
 check($out[0]===$out[1],$name.' changed DTO, result or RNG');$results[]=$name;
}
function attackChecks(array $events,string $type):void{check(count(es($events,'attack.declared'))===1,'declaration once '.$type);$r=es($events,'attack.result');check(count($r)===1&&$r[0]['payload']['attack_type']===$type,'result once '.$type);check(count(es($events,'dice.rolled'))===1,'one real die '.$type);check(count(es($events,'dice.final'))===1,'one final die '.$type);$order=array_column($events,'type');check(array_search('attack.declared',$order)<array_search('dice.rolled',$order)&&array_search('dice.rolled',$order)<array_search('dice.final',$order)&&array_search('dice.final',$order)<array_search('attack.result',$order),'declaration / roll / final / result order '.$type);foreach($events as$e)if(in_array($e['type'],['movement.completed','zone.changed','card.transformed'],true))check(!isset($e['payload']['defend']),'no artificial defender');}

function movementCheck(array $es,string $kind='jump'):void{$ms=es($es,'movement.completed');check(count($ms)===1,'one movement');check($ms[0]['payload']['movement_type']===$kind,'actual movement kind');check($ms[0]['payload']['from']===[3,3]&&$ms[0]['payload']['to']===[4,4],'actual coordinates');}
foreach(['s1_89','s1_107','s1_145','s1_155','s1_182','s1_185','s1_191']as$key){$s=seed($key);pair('jump '.$key,$s,fn($s)=>cmd($s,'host','jump',['card_id'=>1,'row'=>4,'col'=>4]),function($es)use($key){movementCheck($es);if($key==='s1_185'){ $order=array_column($es,'type');check(array_search('movement.completed',$order)<array_search('dice.rolled',$order),'jump before its actual roll');}});}
$s=seed('s1_1');pair('ordinary move',$s,fn($s)=>cmd($s,'host','move',['card_id'=>1,'row'=>3,'col'=>4]),function($es){$m=es($es,'movement.completed');check(count($m)===1&&$m[0]['payload']['from']===[3,3]&&$m[0]['payload']['to']===[3,4],'one real ordinary movement');$lines=[];foreach($es as$e)if($e['host']&&($line=JournalText::format($e['type'],$e['host'])))$lines[]=$line;check(count(array_filter($lines,fn($t)=>str_contains($t,'перемещается')))===1,'no legacy move text duplicate');});
foreach(['hidden','rejected','repeat','blocked']as$case){$s=seed('s1_89');if($case==='hidden')$s->cards[1]->revealed=false;if($case==='blocked')$s->cards[1]->markers['rooted']=['value'=>1];pair('jump '.$case,$s,function($s)use($case){$r=(new Engine())->apply($s,$case==='rejected'?'player':'host',new Command('jump',['card_id'=>1,'row'=>4,'col'=>4]));if($case==='repeat'){check($r->success,'first jump');$before=$s->toArray();check(!(new Engine())->apply($s,'host',new Command('jump',['card_id'=>1,'row'=>4,'col'=>4]))->success&&$before===$s->toArray(),'repeat inert');}return$r;},function($es)use($case){if(in_array($case,['rejected','blocked'],true))check(!es($es,'movement.completed'),'failed jump not recorded');else{movementCheck($es);if($case==='hidden'){ $e=es($es,'movement.completed')[0];check($e['host']!==null&&$e['player']===null,'hidden movement projection');}}});}
$s=seed('s1_1');pair('forced move hidden external cause',$s,function($s){$s->historyRecorder?->commandStarted($s,'host',new Command('fixture'));return(new \Berserk\Core\Movement\ForcedMovementResolver($s,new Engine()))->move($s->cards[2],-1,0);},function($es){$m=es($es,'movement.completed');check(count($m)===1&&$m[0]['payload']['movement_type']==='forced_move','forced once');foreach(['host','player']as$v)check($m[0][$v]!==null&&!isset($m[0][$v]['source_id']),'visible target without hidden cause');});
foreach([false,true]as$hidden){$s=seed('s1_105');$s->cards[1]->zone='deck';$s->cards[1]->row=$s->cards[1]->col=null;$s->cards[1]->revealed=!$hidden;pair('summon '.(int)$hidden,$s,function($s){$s->historyRecorder?->commandStarted($s,'host',new Command('fixture'));(new \Berserk\Core\ZoneManager($s))->summonFromDeck($s->cards[1],4,4);},function($es){$e=es($es,'zone.changed');check(count($e)===1&&$e[0]['payload']['reason']==='summon','one actual summon');check($e[0]['host']!==null&&$e[0]['player']!==null,'summoned revealed card known to both');});}
foreach([false,true]as$hidden){$s=seed('s1_54');$s->cards[1]->revealed=!$hidden;$s->battle['pending_prophecy']=['owner'=>'host','source_id'=>1,'meta'=>['all_elite'=>true]];pair('seeker transform '.(int)$hidden,$s,fn($s)=>(new \Berserk\Core\ProphecyProcessor($s,new Engine()))->transformSeeker('host'),function($es)use($hidden){$e=es($es,'card.transformed');check(count($e)===1&&!es($es,'zone.changed'),'single transform no zone duplicate');check($e[0]['host']['before']['type']==='creature'&&$e[0]['host']['after']['type']==='fly','actual forms');if($hidden)check($e[0]['player']===null,'hidden transform');});}
$s=seed('s1_68');pair('active gain flight',$s,fn($s)=>cmd($s,'host','action',['card_id'=>1,'action_key'=>'become_fly']),function($es){check(count(es($es,'card.transformed'))===1&&!es($es,'zone.changed'),'flight once');});
$s=seed('s1_1');pair('exile repeat',$s,function($s){$s->historyRecorder?->commandStarted($s,'host',new Command('fixture'));$z=new \Berserk\Core\ZoneManager($s);$z->toExile($s->cards[2]);$z->toExile($s->cards[2]);},function($es){check(count(es($es,'zone.changed'))===1&&!es($es,'combat.death'),'exile is not death, repeat no event');});
$s=seed('s1_1');pair('ordinary death no zone noise',$s,function($s){$s->historyRecorder?->commandStarted($s,'host',new Command('fixture'));(new \Berserk\Core\DamageResolver($s))->forceDeath($s->cards[2],'strike',$s->cards[1]);(new Engine())->finalizeDying($s);},function($es){check(count(es($es,'combat.death'))===1&&!es($es,'zone.changed'),'single death');});
$s=seed('s1_42');$s->cards[1]->coins=3;$s->cards[3]->zone='graveyard';$s->cards[3]->revealed=false;$s->cards[3]->hp=0;$s->cards[3]->row=$s->cards[3]->col=null;pair('native revive pending',$s,function($s){cmd($s,'host','action',['card_id'=>1,'action_key'=>'revive']);cmd($s,'host','choose_revive_target',['target_id'=>3]);$r=cmd($s,'host','choose_revive_cell',['row'=>4,'col'=>4]);$before=$s->toArray();check(!(new Engine())->apply($s,'host',new Command('choose_revive_cell',['row'=>4,'col'=>4]))->success&&$before===$s->toArray(),'stale revive inert');return$r;},function($es){$e=es($es,'zone.changed');check(count($e)===1&&$e[0]['payload']['from_zone']==='graveyard'&&$e[0]['player']!==null,'revival frozen after reveal');check(!es($es,'combat.death'),'revive not death');});
$s=seed('s1_198');$s->cards[1]->coins=1;pair('native teleport pending',$s,function($s){cmd($s,'host','action',['card_id'=>1,'target_id'=>2,'action_key'=>'dimension_door']);return cmd($s,'host','choose_teleport_cell',['cell'=>'4_4']);},function($es){$m=es($es,'movement.completed');check(count($m)===1&&$m[0]['payload']['movement_type']==='teleport','teleport once');});

$s=seed('s1_141');$s->cards[1]->zone='graveyard';$s->cards[1]->hp=0;$s->cards[1]->row=$s->cards[1]->col=null;$s->battle['pending_incarnation']=['owner'=>'host','current'=>1,'queue'=>[1]];pair('ground incarnation native',$s,fn($s)=>cmd($s,'host','choose_incarnation_cell',['row'=>1,'col'=>3]),function($es){$e=es($es,'zone.changed');check(count($e)===1&&$e[0]['payload']['reason']==='incarnation','incarnation once');});
$s=seed('s1_137');$s->cards[1]->zone='graveyard';$s->cards[1]->hp=0;$s->cards[1]->row=$s->cards[1]->col=null;pair('flying incarnation native',$s,function($s){$s->historyRecorder?->commandStarted($s,'host',new Command('fixture'));(new ReflectionMethod(\Berserk\Core\TurnProcessor::class,'incarnateFlyer'))->invoke(new \Berserk\Core\TurnProcessor($s,new Engine()),$s->cards[1],$s->cards[1]->prop['incarnation']);},function($es){$e=es($es,'zone.changed');check(count($e)===1&&$e[0]['payload']['to_zone']==='flying','flying incarnation return');});
$s=seed('s1_54');$s->cards[1]->revealed=false;pair('form visibility boundary contract',$s,function($s){$s->historyRecorder?->commandStarted($s,'host',new Command('fixture'));$before=$s->historyRecorder?->formBefore($s,$s->cards[1]);$s->cards[1]->type='fly';$s->cards[1]->revealed=true;if($before!==null)$s->historyRecorder->transformed($s,$s->cards[1],$before);},function($es){$e=es($es,'card.transformed')[0];check($e['host']['before']['type']==='creature'&&$e['player']['before']===null&&$e['player']['after']['type']==='fly','old hidden form not exposed');check(!isset($e['player']['_before_forms']),'other view private forms not leaked');});
$s=seed('s1_54');$s->battle['pending_prophecy']=['owner'=>'host','source_id'=>1,'meta'=>['all_elite'=>true]];pair('same form not a second transformation',$s,function($s){$p=new \Berserk\Core\ProphecyProcessor($s,new Engine());$p->transformSeeker('host');$p->transformSeeker('host');},function($es){check(count(es($es,'card.transformed'))===1,'no fake second form change');});
$s=seed('s1_89');$s->cell_markers['4_4']=['type'=>'bonfire'];pair('jump blocked cell marker',$s,fn($s)=>(new Engine())->apply($s,'host',new Command('jump',['card_id'=>1,'row'=>4,'col'=>4])),function($es){check(!es($es,'movement.completed'),'blocked cell not traversed');});

$s=seed('s1_1');$s->cards[2]->flags['incarnated']=true;pair('incarnated death and exile are distinct',$s,function($s){$s->historyRecorder?->commandStarted($s,'host',new Command('fixture'));(new \Berserk\Core\DamageResolver($s))->forceDeath($s->cards[2],'strike',$s->cards[1]);(new Engine())->finalizeDying($s);},function($es){check(count(es($es,'combat.death'))===1&&count(es($es,'zone.changed'))===1,'death once and actual exile once');});
$s=seed('s1_89');$s->cell_markers['4_4']=['type'=>'bomb'];pair('jump across nonblocking cell marker',$s,fn($s)=>cmd($s,'host','jump',['card_id'=>1,'row'=>4,'col'=>4]),function($es,$s){movementCheck($es);check(isset($s->cell_markers['4_4']),'movement does not invent marker consumption');});

$s=seed('s1_185');pair('Shaksi jump nested wounds continuation',$s,function($s){cmd($s,'host','jump',['card_id'=>1,'row'=>4,'col'=>4]);check(isset($s->battle['pending_shaksi_roll']),'actual Shaksi choice');return cmd($s,'host','choose_shaksi_roll',['target_id'=>2]);},function($es){$types=array_column($es,'type');check(count(es($es,'movement.completed'))===1&&count(es($es,'combat.wounds'))===1,'movement and nested wound once');check(array_search('movement.completed',$types)<array_search('dice.rolled',$types)&&array_search('dice.rolled',$types)<array_search('combat.wounds',$types),'movement before die before nested damage');},'1,6,2,5,3');
